for m in range(2, 11):
    # edges: e (index 0), e_0..e_{m-1} (index 1..m); triangles T_i: boundary e - e_{i+1} + e_i
    def delta1(phi):
        return [(phi[0] - phi[1 + (i+1) % m] + phi[1 + i]) % m for i in range(m)]
    cocycles = []
    for a0 in range(m):
        for ae in range(m):
            phi = [ae] + [(a0 + i*ae) % m for i in range(m)]
            assert delta1(phi) == [0]*m
            cocycles.append(tuple(phi))
    assert len(set(cocycles)) == m*m
    # image of delta1: count by brute force for small m
    if m <= 5:
        img = set()
        for phi in itertools.product(range(m), repeat=m+1):
            img.add(tuple(delta1(list(phi))))
        assert len(img) == m**(m-1)
        assert all(sum(x) % m == 0 for x in img)
    # coboundaries of 0-cochains (f(v), f(w)): spokes get f(w)-f(v), e gets 0
    B1 = {tuple([0] + [t % m]*m) for t in range(m)}
    assert len(B1) == m and B1 <= set(cocycles)
    phi = [1] + [i % m for i in range(m)]
    sq = [phi[1+i]*phi[0] % m for i in range(m)]   # front edge e_i, back edge e
    val = sum(sq) % m
    if m % 2:
        assert val == 0
    else:
        assert val == m//2
