V = range(7)
simp = {n: list(itertools.combinations(V, n+1)) for n in range(7)}
def delta(phi, n): return {s: sum((-1)**i * phi[s[:i]+s[i+1:]] for i in range(n+2)) for s in simp[n+1]}
def dM(phi, n): return {s: (-1)**(n+1) * v for s, v in delta(phi, n).items()}
def cupM(phi,k,psi,l): return {s: (-1)**(k*l) * phi[s[:k+1]]*psi[s[k:]] for s in simp[k+l]}
def rnd(n): return {s: random.randint(-3,3) for s in simp[n]}
for k in range(0,3):
    for l in range(0,3):
        phi, psi = rnd(k), rnd(l)
        lhs = dM(cupM(phi,k,psi,l), k+l)
        a = cupM(dM(phi,k), k+1, psi, l); b = cupM(phi, k, dM(psi,l), l+1)
        assert all(lhs[s] == a[s] + (-1)**k * b[s] for s in simp[k+l+1])

