    """simplices: dict n -> sorted list of vertex tuples (closed under faces). returns dims, bd"""
    N = max(simplices) + 1
    idx = {n: {s: i for i, s in enumerate(simplices[n])} for n in simplices}
    dims = [len(simplices.get(n, [])) for n in range(N)]
    bd = {}
    for n in range(1, N):
        M = [[0] * dims[n] for _ in range(dims[n - 1])]
        for j, s in enumerate(simplices[n]):
            for i in range(n + 1):
                f = s[:i] + s[i + 1:]
                M[idx[n - 1][f]][j] += (-1) ** i
        bd[n] = Matrix(M)
    return dims, bd

def closure(maximal):
    S = {}
    for m in maximal:
        m = tuple(sorted(m))
        for k in range(1, len(m) + 1):
            for f in itertools.combinations(m, k):
                S.setdefault(k - 1, set()).add(f)
    return {n: sorted(S[n]) for n in S}


import sympy as sp
from collections import Counter
# octagon P0..P7 with boundary word a1 b1 a1^-1 b1^-1 a2 b2 a2^-1 b2^-1; fan from P0.
# each triangle gets a vertex order making every identified edge keep its orientation
E = {(0,1):'a1',(1,2):'b1',(3,2):'a1',(4,3):'b1',(4,5):'a2',(5,6):'b2',(7,6):'a2',(0,7):'b2'}
for j in range(2,7): E[(0,j)] = 'd%d' % j
tris = [((0,1,2),1),((0,3,2),-1),((0,4,3),-1),((0,4,5),1),((0,5,6),1),((0,7,6),-1)]
for (p,q,r),sg in tris:
    for e in [(p,q),(q,r),(p,r)]: assert e in E
cnt = Counter()
for (p,q,r),sg in tris:
    for e,c in [((q,r),1),((p,r),-1),((p,q),1)]: cnt[E[e]] += sg*c
assert all(v == 0 for v in cnt.values())          # fundamental cycle
names = ['a1','b1','a2','b2'] + ['d%d' % j for j in range(2,7)]
X = dict(zip(names, sp.symbols(' '.join(names))))
eqs = [X[E[(q,r)]] - X[E[(p,r)]] + X[E[(p,q)]] for (p,q,r),sg in tris]
A = sp.Matrix([[sp.diff(e, X[n]) for n in names] for e in eqs])
assert len(names) - A.rank() == 4                  # H^1 = Z^1 = Z^4 (one vertex, B^1 = 0)
gens = ['a1','b1','a2','b2']
def cocycle(g):
    sub = {X[h]: (1 if h == g else 0) for h in gens}
    sol = sp.solve([e.subs(sub) for e in eqs], [X['d%d' % j] for j in range(2,7)], dict=True)[0]
    f = {h: sub[X[h]] for h in gens}
    for j in range(2,7): f['d%d' % j] = sol[X['d%d' % j]]
    assert all(v == int(v) for v in f.values())
    return f
co = {g: cocycle(g) for g in gens}
def cup_on_cycle(f, g):
    return sum(sg * f[E[(p,q)]] * g[E[(q,r)]] for (p,q,r),sg in tris)
M = sp.Matrix(4, 4, lambda i,j: cup_on_cycle(co[gens[i]], co[gens[j]]))
J = sp.Matrix([[0,1],[-1,0]])
assert M == sp.diag(J, J) or M == -sp.diag(J, J)
